      --bg: #f4f7fb;
      --card: rgba(255, 255, 255, 0.92);
      --text: #0f172a;
      --muted: #64748b;
      --border: #d7e0ec;
      --focus: #2563eb;
      --accent: #1d4ed8;
      --accent-hover: #1e40af;
      --error: #b91c1c;
      --shadow: 0 20px 50px rgba(15, 23, 42, 0.12);
      --radius: 20px;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
