      box-shadow: var(--shadow);
      backdrop-filter: blur(16px);
      padding: clamp(24px, 4vw, 40px);
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-weight: 600;
      font-size: 0.95rem;
    }

    input {
      width: 100%;
      border: 1px solid var(--border);
      border-radius: 14px;
      background: #fff;
      color: var(--text);
      padding: 14px 16px;
      font: inherit;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
    }

    input::placeholder {
      color: #94a3b8;
    }

    input:focus {
      outline: none;
      border-color: var(--focus);
      box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.14);
    }

    .helper-text {
      color: var(--muted);
      font-size: 0.9rem;
      line-height: 1.4;
    }

    .error-text {
      color: var(--error);
      font-size: 0.9rem;
      line-height: 1.4;
      min-height: 1.2em;
      visibility: hidden;
