    button:hover {
      background: linear-gradient(135deg, var(--accent-hover), #0b5ee8);
      transform: translateY(-1px);
      box-shadow: 0 16px 28px rgba(29, 78, 216, 0.28);
    }

    button:focus-visible {
      outline: 3px solid rgba(37, 99, 235, 0.35);
      outline-offset: 3px;
    }

    .status {
      margin-top: 12px;
      min-height: 1.25em;
      color: var(--accent);
      font-weight: 600;
    }

    @media (max-width: 640px) {
      body { padding: 16px; }
      .card { padding: 20px; }
      button { width: 100%; }
      .actions { display: block; }
    }
  </style>
</head>
<body>
  <main class="page-shell">
    <section class="hero" aria-labelledby="page-title">
      <span class="eyebrow">Support</span>
      <h1 id="page-title">Contact our team</h1>
      <p>Send a message to support and we’ll get back to you as soon as possible.</p>
    </section>

    <section class="card" aria-label="Contact form">
      <form id="support-form" novalidate>
        <div class="form-field" data-field="fullName">
          <label for="fullName">Full name</label>
          <input id="fullName" name="fullName" type="text" autocomplete="name" required placeholder="Ada Lovelace">
          <div class="error-text" aria-live="polite"></div>
        </div>

        <div class="form-field" data-field="email">
          <label for="email">Email address</label>
          <input id="email" name="email" type="email" autocomplete="email" required placeholder="ada@example.com">
          <div class="error-text" aria-live="polite"></div>
        </div>

        <div class="form-field" data-field="phone">
          <label for="phone">Phone number</label>
          <input id="phone" name="phone" type="tel" autocomplete="tel" placeholder="(555) 123-4567">
          <div class="helper-text" id="phone-help">Use a format like +1 555 123 4567 or (555) 123-4567.</div>
          <div class="error-text" aria-live="polite"></div>
        </div>

        <div class="actions">
          <button type="submit">Submit request</button>
        </div>
        <div class="status" id="form-status" aria-live="polite"></div>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('support-form');
    const status = document.getElementById('form-status');
    const fields = {
      fullName: document.getElementById('fullName'),
      email: document.getElementById('email'),
      phone: document.getElementById('phone'),
    };

    function setFieldError(input, message) {
      const field = input.closest('.form-field');
      const error = field.querySelector('.error-text');
      field.dataset.invalid = message ? 'true' : 'false';
      error.textContent = message;
    }

    function validate() {
      let valid = true;

      if (!fields.fullName.value.trim()) {
        setFieldError(fields.fullName, 'Full name is required.');
        valid = false;
      } else {
        setFieldError(fields.fullName, '');
      }

      if (!fields.email.value.trim()) {
        setFieldError(fields.email, 'Email address is required.');
        valid = false;
      } else if (!fields.email.validity.valid) {
        setFieldError(fields.email, 'Enter a valid email address.');
        valid = false;
      } else {
        setFieldError(fields.email, '');
      }

      const phoneValue = fields.phone.value.trim();
      if (phoneValue && !/^[+()\-.\s\d]{7,}$/.test(phoneValue)) {
        setFieldError(fields.phone, 'Enter a valid phone number format.');
        valid = false;
      } else {
        setFieldError(fields.phone, '');
      }

      return valid;
    }

    form.addEventListener('submit', (event) => {
      event.preventDefault();
      status.textContent = '';

      if (validate()) {
        status.textContent = 'Thanks — your request is ready to send.';
        form.reset();
        Object.values(fields).forEach((input) => setFieldError(input, ''));
      }
    });

    Object.values(fields).forEach((input) => {
      input.addEventListener('input', () => {
        if (input.value.trim()) {
          setFieldError(input, '');
        }
      });
    });
  </script>
</body>
</html>
