 <!doctype html>
 <html lang="en">
 <head>
   <meta charset="utf-8">
   <meta name="viewport" content="width=device-width, initial-scale=1">
   <title>Support Contact Form</title>
   <style>
     :root {
       color-scheme: light;
       --bg: #f4f7fb;
       --card: rgba(255, 255, 255, 0.92);
       --text: #0f172a;
       --muted: #64748b;
       --border: #d7e0ec;
       --focus: #2563eb;
       --accent: #1d4ed8;
       --accent-hover: #1e40af;
       --error: #b91c1c;
       --shadow: 0 20px 50px rgba(15, 23, 42, 0.12);
       --radius: 20px;
     }

     * { box-sizing: border-box; }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       color: var(--text);
       background:
         radial-gradient(circle at top, rgba(37, 99, 235, 0.12), transparent 35%),
         linear-gradient(180deg, #eef4ff 0%, var(--bg) 100%);
       display: grid;
       place-items: center;
       padding: 24px;
     }

     .page-shell {
       width: min(100%, 760px);
     }

     .hero {
       margin-bottom: 20px;
     }

     .eyebrow {
       display: inline-flex;
       align-items: center;
       gap: 8px;
       padding: 8px 12px;
       border-radius: 999px;
       background: rgba(37, 99, 235, 0.1);
       color: var(--accent);
       font-size: 0.875rem;
       font-weight: 600;
     }

     h1 {
       margin: 14px 0 8px;
       font-size: clamp(2rem, 4vw, 3.25rem);
       line-height: 1.05;
       letter-spacing: -0.04em;
     }

     .hero p {
       margin: 0;
       max-width: 60ch;
       color: var(--muted);
       font-size: 1.05rem;
       line-height: 1.6;
     }

     .card {
       background: var(--card);
       border: 1px solid rgba(215, 224, 236, 0.9);
       border-radius: var(--radius);
       box-shadow: var(--shadow);
       backdrop-filter: blur(16px);
       padding: clamp(24px, 4vw, 40px);
     }

     form {
       display: grid;
       gap: 18px;
     }

     .form-field {
       display: grid;
       gap: 8px;
     }

     label {
       font-weight: 600;
       font-size: 0.95rem;
     }

     input {
       width: 100%;
       border: 1px solid var(--border);
       border-radius: 14px;
       background: #fff;
       color: var(--text);
       padding: 14px 16px;
       font: inherit;
       transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
     }

     input::placeholder {
       color: #94a3b8;
     }

     input:focus {
       outline: none;
       border-color: var(--focus);
       box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.14);
     }

     .helper-text {
       color: var(--muted);
       font-size: 0.9rem;
       line-height: 1.4;
     }

     .error-text {
       color: var(--error);
